package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.workflow.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ForEachNodeExecutorTest {@Test void capturesCollectionAndEnforcesBudgetParallelism(){Map<String,Object> variables=new HashMap<>();variables.put("shopIds",Arrays.asList(1L,2L));WorkflowNodeDefinition node=NodeExecutorTestSupport.node("each",WorkflowNodeType.FOREACH,"{\"collectionVariable\":\"shopIds\"}");NodeExecutionResult result=new ForEachNodeExecutor(new ObjectMapper()).execute(NodeExecutorTestSupport.context(node,variables,Collections.emptyList()));assertEquals(2,result.getOutput().size());assertEquals(4,result.getVariableUpdates().get("each.maxParallelism"));}}
